var e={"maxxing.toggle":`Maxxing`,"maxxing.on":`Maxxingモード：セッションが終了すると、すぐに次の指示を入力できるよう、そのセッションが大きく前面に表示されます`,"maxxing.off":`Maxxingモードはオンです - クリックでオフにします`,"maxxing.next":`次のセッション`,"maxxing.back":`戻る`,"maxxing.backTip":`前のセッションに戻ります（プロンプトが早く送信されすぎた場合）。次に送信するまで前面に残ります`,"maxxing.waiting":`{n}件待機中`,"maxxing.meter.title":`効率`,"maxxing.meter.overdrive":`オーバードライブ`,"maxxing.meter.utilisation":`稼働中のセッション`,"maxxing.meter.delay":`平均応答時間`,"maxxing.meter.answered":`再開したセッション`,"maxxing.meter.hint":`直近10分間の指標：70％はセッションが稼働している時間、30％はあなたの応答の速さ（目標30秒）です。さらに速くなると、バーがあふれます。`};export{e as default};